'use strict';
const ECONOMY_UI6={bind,financeView,boardView,hqView,roastersView,estatesView,bakeryView,help};
function economicFinanceUI6(){const f=state.economy6,h=f.history.at(-1),loan=state.debt?state.debt*economicInterest6():0;return `<section class="card" style="margin-bottom:24px"><span class="eyelabel">SKUTEČNÁ EKONOMIKA · 05.15</span><h2>Disponibilní peníze a plný výsledek</h2><div class="report-overview5">${metric('K DISPOZICI',money(state.cash),'Pro investice a provoz')}${metric('VYČLENĚNÉ DANĚ',money(f.vatEscrow+f.corporateEscrow),'Nejsou volným kapitálem')}${metric('BONITA / CELKOVÝ LIMIT',money(economicCreditLimit6()),'Zbývá '+money(Math.max(0,economicCreditLimit6()-state.debt)))}${metric('ČISTÝ VÝSLEDEK',h?money(h.netProfit):'—','Po odvodech, odpisech a dani')}</div>${h?rows([['Tržby vlastních kaváren včetně DPH',money(h.grossRetail)],['Tržby firmy bez DPH',money(h.netRevenue)],['Zisk před daní',money(h.operating)],['Daň z výsledku / změna rezervy',money(h.incomeTax)],['Zisk po dani',money(h.netProfit)],['Odvody zaměstnavatele',money(h.employer)],['Nezaplacené účetní odpisy',money(h.depreciation)],['Splacená jistina úvěru',money(h.principal)]]):empty('První provozní týden ukáže plné náklady.')}<details><summary>Jak se účtuje hotovost a zisk</summary><p class="sub">Ceny pro hosty obsahují herní DPH (nápoje 21 %, jídlo a balená káva 12 %); tržby firmy ji nezahrnují. Dodavatelské a B2B ceny jsou čisté ceny bez DPH a vstupní DPH je v modelu průběžně vyrovnaná. Daně se vyčleňují do rezervy, která nejde utratit. DPH se odvádí po čtyřech týdnech; zisková daň 21 % se vyrovná po třinácti týdnech, průběžná ztráta vrátí rezervu a starší ztráta sníží další základ. Jedná se o jednotný český herní model i v zahraničních městech.</p><p class="sub">Mzdy jmenného týmu jsou hrubé; firma navíc platí 33,8 % odvodů a případný přesčas. Rozdíl lokálních mezd roste s cenovou hladinou města. Odpisy vybavení a části budov zatěžují výsledek postupně a nepředstavují další platbu. Koupě provozu, zásob, jistoty a splátka dluhu mění peníze, nikoli okamžitě celý provozní náklad. Pronajaté zázemí dovolí růst bez předčasné koupě budovy.</p></details><div class="fields">${field('Částka podnikatelského úvěru',input('economicLoanAmount6',Math.min(250000,Math.max(10000,Math.floor((economicCreditLimit6()-state.debt)/10000)*10000)),10000,20000000,10000))}</div><button class="soft" id="economicLoan6">Prověřit a sjednat úvěr</button><p class="sub">${number(ECONOMY_RULES6.annualLoan*100,1)} % ročně, současný úrok přibližně ${money(loan)}/týden. Jistina se splácí průběžně pět let. Výsledek a majetek ovlivňují bonitu; investor platí za podíl podle skutečného ocenění firmy.</p></section>`;}
financeView=function(){return economicFinanceUI6()+ECONOMY_UI6.financeView().replace('Investor +2 000 000 Kč','Investor podle ocenění').replace('Úvěr až +400 000 Kč','Prověřit úvěr').replace(/Úvěrový limit: [^<]+\./,'Úvěrový limit vychází z majetku a výsledku firmy.');};
boardView=function(){const q=state.founderShare>25?investorQuote6():null;return ECONOMY_UI6.boardView().replace('Investor vloží 2 miliony Kč za 25 procentních bodů firmy.',q?'Investor nabídne '+money(q.amount)+' za pokles tvého podílu o 25 procentních bodů.':'Další podíl už nenabízíš.').replace('Prodat 25 % · +2 miliony Kč',q?'Prověřit investici · '+money(q.amount):'Investor není dostupný').replace('Investice 180 000 Kč zvýší její nominální kapacitu o 100 kg zelené kávy za směnu.',state.roasters[0].tenure6==='contract'?'Smluvní zařízení patří dodavateli. Nejprve pořiď vlastní pražírnu.':'Investice 180 000 Kč zvýší nominální kapacitu první vlastní pražírny o 100 kg a její účetní hodnotu.');};
hqView=function(){return `<section class="card" style="margin-bottom:24px"><h2>Pronajaté zázemí firmy</h2><p class="sub">Vlastní kancelář je dlouhodobá investice. Oddělení mohou začít v pronájmu; kapacita pracovních míst funguje stejně.</p><div class="cards">${OFFICE_OPTIONS.map(o=>{const l=OFFICE_LEASES6[o.id];return `<article><h3>${esc(o.name)}</h3>${rows([['Pracovní místa',o.seats],['Vybavení a vratná jistota',money(l.cost+l.deposit)],['Týdenní nájem',money(l.rent)]])}<button class="soft" data-lease-office6="${o.id}" ${state.cash<l.cost+l.deposit||state.offices.length>=4?'disabled':''}>Pronajmout kanceláře</button></article>`;}).join('')}</div></section>`+ECONOMY_UI6.hqView().replaceAll('VLASTNÍ NEMOVITOST','ZÁZEMÍ FIRMY');};
roastersView=function(){return `<section class="card" style="margin-bottom:24px"><h2>Smluvní pražení a vlastní výroba</h2><p class="sub">Smluvní pražírna na začátku je externí služba: 4 500 Kč/týden za rezervovanou kapacitu plus zpracování skutečně pražených kg. Nepatří firmě a nezvyšuje její majetek. Vlastní linka má zaměstnance, odvody, provoz a odpisy; její koupě potřebuje podstatně více kapitálu.</p></section>`+ECONOMY_UI6.roastersView();};
estatesView=function(){return `<p class="intro">Kupuješ zavedenou produkční plantáž. Cena zahrnuje pozemky a provoz; cyklus zralých porostů trvá 26 týdnů a sklizeň musí zaplatit celý pěstitelský cyklus. Vlastní původ je investice pro vybudovanou síť.</p>`+ECONOMY_UI6.estatesView();};
bakeryView=function(){return `<p class="sub">Výrobní investice mají nové ceny. Fixní náklad pekárny zahrnuje místní mzdy a odvody. Výsledek řetězce v reportu je po DPH; tržby jednotlivých kusů a denní vitríny ukazují cenu pro hosta.</p>`+ECONOMY_UI6.bakeryView();};
bind=function(){ECONOMY_UI6.bind();const loan=()=>{try{const q=economicLoanQuote6(el('economicLoanAmount6')?Number(el('economicLoanAmount6').value):undefined);confirmAction('Sjednat podnikatelský úvěr?',money(q.amount)+' při '+number(q.annual*100,1)+' % ročně; jistina přibližně '+money(q.weeklyPrincipal)+'/týden a úrok '+money(q.weeklyInterest)+'/týden. Aktuální celkový limit '+money(q.limit)+'.',()=>takeLoan(q.amount,q));}catch(e){toast(e.message);}};if(el('economicLoan6'))el('economicLoan6').onclick=loan;if(el('loan'))el('loan').onclick=loan;if(el('investor'))el('investor').onclick=()=>{try{const q=investorQuote6();confirmAction('Přijmout investora?',money(q.amount)+' za pokles podílu z '+q.shareBefore+' % na '+q.shareAfter+' %. Ocenění před investicí '+money(q.valuation)+'. Pod 50 % rozhoduje expanzní mandát boardu.',()=>raiseCapital(q),'Přijmout investici');}catch(e){toast(e.message);}};on('[data-lease-office6]',b=>{try{const q=leaseOfficeQuote6(b.dataset.leaseOffice6);confirmAction('Pronajmout zázemí firmy?',esc(q.name)+' · '+money(q.cost)+' vstupně, z toho '+money(q.deposit)+' vratná jistota. Nájem '+money(q.rent)+'/týden.',()=>leaseOffice6(q.type,q));}catch(e){toast(e.message);}});};
help=function(){ECONOMY_UI6.help();const p=document.createElement('p');p.textContent='Edice 05.15: Pomalejší růst stojí na plných mzdách, zaměstnavatelských odvodech, DPH oddělené od tržeb, dani ze skutečného výsledku, odpisech a splátkách jistiny. První pražení je smluvní služba, kanceláře lze pronajmout. Vlastní nemovitosti, pekárny, výrobní linky a plantáže stojí miliony. Investor a banka vycházejí z ocenění, výsledků a současného dluhu. Hra používá jednotný český finanční model s místní cenovou hladinou, ne skutečné účetnictví každé země.';el('modalContent').append(p);};el('help').onclick=help;render();
